def compose_operations(html: str) -> str:
    """Compose the local visual desk while preserving all established handler IDs."""
    from .dashboard_network import NETWORK_HTML, NETWORK_SETUP_HTML
    from .dashboard_storage import STORAGE_SETUP_HTML, STORAGE_EVIDENCE_HTML
    html = re.sub(r'<section class="hero" aria-labelledby="page-title">.*?</section>', '<h1 id="page-title" class="sr-only" tabindex="-1">MEGALODON visual HUD</h1>', html, count=1, flags=re.S)
    html, setup = _take(html, 'support-config')
    setup = setup.replace(' hidden>', '>', 1).replace('Close configuration', 'Return to HUD')
    html, software = _take(html, 'setup') if 'id="setup"' in html else (html, '')
    # SETUP_HTML has a section ID in current releases; retain its exact source otherwise.
    if not software:
        from .dashboard_setup import SETUP_HTML
        if SETUP_HTML not in html:
            raise AssertionError('setup shelf missing')
        software = SETUP_HTML
        html = html.replace(software, '', 1)
    html, start = _take(html, 'support-apps')
    start = start.replace('Configure apps</button>', 'Setup</button>').replace('<p class="eyebrow">BACKGROUND WORKSPACE</p>', '').replace('<h3 id="support-apps-title" tabindex="-1">Background tools</h3>', '<h3 id="support-apps-title" tabindex="-1">Background tools</h3>')
    html, resources = _take(html, 'pc-live')
    resources, speeds = _take(resources, 'pc-network-panel')
    resources, live_controls = _take(resources.replace('<div class="pc-live-controls">', '<div class="pc-live-controls" id="ops-live-controls">', 1), 'ops-live-controls')
    resources, freshness = _take(resources, 'pc-freshness')
    speeds += '<div class="ops-speed-footer">' + live_controls + freshness + '</div><p class="ops-note">Measured on the selected interface, including local-network traffic. VPNs and bridges can count the same exchange again.</p>'
    resources = '<details class="ops-resource-detail"><summary>Computer resources &amp; background app costs</summary>' + resources + '</details>'
    html, globe = _take(html, 'live-globe')
    geo_start = globe.index('<button id="live-geography-refresh"')
    geo_end = globe.index('<time id="live-globe-updated"', geo_start)
    geography = globe[geo_start:geo_end]
    globe = globe[:geo_start] + '<a class="ops-setup-link" href="#setup-location-title">Location setup →</a>' + globe[geo_end:]
    globe = globe.replace('<h4>Your approximate internet exit</h4>', '<h4>Approximate internet exit</h4>')
    html, traffic = _take(html, 'workspace-traffic')
    traffic = re.sub(r'^<section[^>]*>', '<section class="ops-stored-events">', traffic).replace('<a class="hud-return" href="#room-home-title">Return to visual HUD →</a>', '')
    # Advanced commands, app launching and capability references belong with setup.
    advanced_match = re.search(r'<details class="workflow-advanced">', html)
    advanced = ''
    if advanced_match:
        html = html[:advanced_match.start()] + html[advanced_match.start():].replace('<details class="workflow-advanced">', '<details class="workflow-advanced" id="ops-advanced-setup">', 1)
        html, advanced = _take(html, 'ops-advanced-setup')
    home_start = html.index('<section class="room-home panel"')
    home_title_end = html.index('  <div class="hud-metrics"', home_start)
    intro = html[home_start:home_title_end]
    html = html.replace(intro, '<section class="room-home panel" aria-labelledby="room-home-title"><h2 id="room-home-title" class="sr-only" tabindex="-1">Visual HUD</h2>' + OPERATIONS_HTML.replace('<!-- OPS_START -->',start).replace('<!-- OPS_RESOURCES -->',resources).replace('<!-- OPS_GLOBE -->',globe).replace('<!-- OPS_SPEED -->',speeds).replace('<!-- OPS_NETWORK -->', NETWORK_HTML) + '<details class="ops-history" id="operations-history"><summary>Stored evidence, history and computer observations</summary><p id="room-home-summary">Stored evidence is checked separately from current activity.</p>', 1)
    # End history immediately before the original home section ends.
    home_end = html.index('\n</section>', html.index('<div class="room-actions"', home_start))
    html = html[:home_end] + traffic + '</details>' + html[home_end:]
    setup_tab = '<section class="workspace-view" id="workspace-setup" role="tabpanel" aria-labelledby="workspace-tab-setup" hidden><header class="ops-setup-head"><p class="eyebrow">CONFIGURE THIS PC</p><h2>Setup &amp; integrations</h2><p>Prepare tools here. Run and investigate from the HUD.</p></header>' + STORAGE_SETUP_HTML + NETWORK_SETUP_HTML + setup + '<section class="ops-location-setup" aria-labelledby="setup-location-title"><h3 id="setup-location-title" tabindex="-1">IP location data</h3>' + geography + '</section>' + software + advanced + '</section>'
    setup_tab = setup_tab.replace('</header>', '</header>' + SETUP_SHORTCUTS_HTML, 1)
    html = html.replace('  <noscript>', setup_tab + '  <noscript>', 1)
    marker = re.search(r'<section[^>]*id="workspace-analysis"[^>]*>', html)
    if not marker:
        raise AssertionError('evidence workspace missing')
    html = html[:marker.end()] + STORAGE_EVIDENCE_HTML + html[marker.end():]
    # Stored range controls are optional history controls, not the live window.
    start_range = html.index('<div class="room-range"')
    end_range = html.index('</div>\n', start_range)+len('</div>\n')
    html = html[:start_range] + '<details class="ops-range"><summary>Stored evidence time range</summary>' + html[start_range:end_range] + '</details>' + html[end_range:]
    return html.replace('<!-- ADDRESS_INVESTIGATION -->', INVESTIGATION_HTML + MAP_HTML, 1)


